<?php
declare(strict_types=1);use ImAuthenticator\Security;use ImAuthenticator\Web;$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$user=$auth->requireUser();$appId=(int)($_GET['id']??0);$app=$db->one('SELECT * FROM applications WHERE id=? AND deleted_at IS NULL',[$appId]);if(!$app){http_response_code(404);Web::page('Nie znaleziono','<div class="alert danger">Nie znaleziono aplikacji.</div>',$user);}if(!$appAdmins->canManage((int)$user['id'],$appId,'manage')){http_response_code(403);Web::page('Brak dostępu','<div class="alert danger">Nie masz uprawnień administracyjnych do tej aplikacji.</div>',$user);}$redirects=array_column($db->all('SELECT redirect_uri FROM application_redirect_uris WHERE application_id=? ORDER BY id',[$appId]),'redirect_uri');$scopes=array_column($db->all('SELECT scope FROM application_scopes WHERE application_id=? ORDER BY scope',[$appId]),'scope');$roles=$db->all('SELECT * FROM app_roles WHERE application_id=? ORDER BY name',[$appId]);$groups=$db->all('SELECT g.*,ag.group_id AS selected FROM user_groups g LEFT JOIN application_groups ag ON ag.group_id=g.id AND ag.application_id=? ORDER BY g.name',[$appId]);$sysRoles=$db->all('SELECT r.*,ar.role_id AS selected FROM system_roles r LEFT JOIN application_system_roles ar ON ar.role_id=r.id AND ar.application_id=? ORDER BY r.name',[$appId]);$issuer=rtrim((string)$config['issuer'],'/');$secret=$_SESSION['client_secrets'][$appId]??null;$secretHtml=$app['client_type']==='public'?'<span class="muted">Public Client — brak sekretu</span>':(is_string($secret)&&$secret!==''?'<code class="secret">'.Web::e($secret).'</code>':'<span class="muted">Sekret jest przechowywany wyłącznie jako hash.</span>');$configRows='<div class="kv"><span>Client Secret</span><div>'.$secretHtml.'</div></div>';foreach(['Issuer URL'=>$issuer,'Client ID'=>$app['client_id'],'Discovery URL'=>$issuer.'/.well-known/openid-configuration','Authorization Endpoint'=>$issuer.'/oauth/authorize','Token Endpoint'=>$issuer.'/oauth/token','UserInfo Endpoint'=>$issuer.'/oauth/userinfo','SAML Metadata'=>$issuer.'/saml/metadata','Scopes'=>implode(' ',$scopes),'Redirect URI'=>$redirects===[]?'Nie dotyczy':implode("\n",$redirects)]as$label=>$value)$configRows.='<div class="kv"><span>'.Web::e($label).'</span><div><code>'.nl2br(Web::e($value)).'</code></div></div>';$groupChecks='';foreach($groups as$g)$groupChecks.='<label class="check"><input type="checkbox" name="group_ids[]" value="'.(int)$g['id'].'" '.($g['selected']?'checked':'').'> '.Web::e($g['name']).'</label>';$sysRoleChecks='';foreach($sysRoles as$r)$sysRoleChecks.='<label class="check"><input type="checkbox" name="system_role_ids[]" value="'.(int)$r['id'].'" '.($r['selected']?'checked':'').'> '.Web::e($r['name']).'</label>';$roleList='';foreach($roles as$r)$roleList.='<li><strong>'.Web::e($r['name']).'</strong></li>';if($roleList==='')$roleList='<li class="muted">Brak ról.</li>';$policyOptions='';foreach(['none'=>'Brak dostępu','all'=>'Wszyscy','users'=>'Wybrani użytkownicy','groups'=>'Grupy','roles'=>'Role','mixed'=>'Mieszane']as$v=>$l)$policyOptions.='<option value="'.$v.'" '.($app['access_policy']===$v?'selected':'').'>'.$l.'</option>';$tabs='<div class="tabs"><a href="#config">Konfiguracja</a>';if($appAdmins->canManage((int)$user['id'],$appId,'manage_users'))$tabs.='<a href="/admin/applications/'.$appId.'/users">Użytkownicy</a>';$tabs.='<a href="#roles">Role</a><a href="#access">Dostęp</a>';if($appAdmins->canManage((int)$user['id'],$appId,'manage_security'))$tabs.='<a href="/admin/applications/'.$appId.'/security">Conditional Access</a><a href="/admin/applications/'.$appId.'/oauth-security">OAuth Security</a>';if($appAdmins->canManage((int)$user['id'],$appId,'manage_config'))$tabs.='<a href="/admin/applications/'.$appId.'/claims">Claims</a><a href="/admin/applications/'.$appId.'/presentation">Branding/Status</a><a href="/admin/applications/'.$appId.'/saml">SAML 2.0</a>';if($appAdmins->canManage((int)$user['id'],$appId,'manage_admins'))$tabs.='<a href="/admin/applications/'.$appId.'/administrators">Właściciele/Admini</a>';$tabs.='</div>';$content='<div class="page-head"><div><h1>'.Web::e($app['name']).'</h1><p>'.Web::e($app['url']).'</p></div><div class="actions"><span class="badge '.((bool)$app['enabled']?'ok':'muted').'">'.((bool)$app['enabled']?'Aktywna':'Wyłączona').'</span>'.($appAdmins->canManage((int)$user['id'],$appId,'manage_config')?'<a class="button" href="/admin/applications/'.$appId.'/edit">Edytuj</a>':'').'</div></div>'.$tabs.'<section class="card" id="config"><h2>Konfiguracja SSO</h2>'.$configRows.'</section><section class="card" id="roles"><h2>Role aplikacyjne</h2><ul>'.$roleList.'</ul></section>';if($appAdmins->canManage((int)$user['id'],$appId,'manage_access'))$content.='<section class="card" id="access"><h2>Polityka dostępu</h2><form method="post" action="/admin/applications/'.$appId.'/access-policy"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><label>Tryb<select name="access_policy">'.$policyOptions.'</select></label><h3>Grupy</h3><div class="checks">'.($groupChecks?:'<span class="muted">Brak grup.</span>').'</div><h3>Role systemowe</h3><div class="checks">'.($sysRoleChecks?:'<span class="muted">Brak ról.</span>').'</div><button class="primary">Zapisz politykę</button></form></section>';Web::page((string)$app['name'],$content,$user);
